package com.brainserve.onboarding.notifications.api.controller;
import com.brainserve.onboarding.common.api.ApiResponse;import com.brainserve.onboarding.common.observability.RequestContext;import com.brainserve.onboarding.common.security.TenantPrincipal;import com.brainserve.onboarding.notifications.api.request.NotificationPreferencesRequest;import com.brainserve.onboarding.notifications.api.response.*;import com.brainserve.onboarding.notifications.application.service.NotificationService;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/notifications") @PreAuthorize("hasAuthority('INTERNAL_SESSION')") public class NotificationController {private final NotificationService service;public NotificationController(NotificationService service){this.service=service;}
@GetMapping ApiResponse<List<NotificationResponse>> list(@AuthenticationPrincipal TenantPrincipal p,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="30")int size){var r=service.list(p,page,size);return ApiResponse.success(r.items(),Map.of("page",r.page(),"size",r.size(),"totalElements",r.totalElements(),"totalPages",r.totalPages(),"unreadCount",r.unreadCount()),RequestContext.requestId());}
@PostMapping("/{id}/read") ApiResponse<NotificationResponse> read(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id){return ApiResponse.success(service.read(p,id),RequestContext.requestId());}
@PostMapping("/read-all") ApiResponse<Map<String,Integer>> readAll(@AuthenticationPrincipal TenantPrincipal p){return ApiResponse.success(Map.of("updated",service.readAll(p)),RequestContext.requestId());}
@GetMapping("/preferences") ApiResponse<NotificationPreferencesResponse> preferences(@AuthenticationPrincipal TenantPrincipal p){return ApiResponse.success(service.preferences(p),RequestContext.requestId());}
@PutMapping("/preferences") ApiResponse<NotificationPreferencesResponse> updatePreferences(@AuthenticationPrincipal TenantPrincipal p,@RequestBody NotificationPreferencesRequest r){return ApiResponse.success(service.updatePreferences(p,r),RequestContext.requestId());}}
